// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 seed, uint256 attackerSeed) public {
        // Admissible domain: any attacker address and any put amount >= MinSum.
        address attacker = address(uint160(uint256(keccak256(abi.encodePacked(seed, "attacker")))) );
        uint256 putAmt = bound(uint256(keccak256(abi.encodePacked(seed, "put"))), 1 ether, 100 ether);
        vm.deal(attacker, putAmt);
        vm.prank(attacker);
        c.Put{value: putAmt}(0);

        // Deploy a re-entrant attacker that calls Collect once more during the receive().
        ReentrantAttacker ra = new ReentrantAttacker(c);
        vm.deal(address(ra), 0);

        // Seed the attacker contract's account by putting from it.
        uint256 raPut = bound(uint256(keccak256(abi.encodePacked(seed, "raput"))), 1 ether, 50 ether);
        vm.deal(address(ra), raPut);
        ra.doPut{value: raPut}(0);

        // Let time pass so unlockTime is satisfied.
        vm.warp(block.timestamp + 1 days);

        // Record pre-state.
        (, uint256 balBefore) = c.Acc(address(ra));

        // The reentrant attacker attempts to Collect; its receive() tries Collect again
        // up to the amount that would make its balance negative if double-processed.
        ra.attack();

        (, uint256 balAfter) = c.Acc(address(ra));

        // General rule: after Collect completes, the account balance must never be
        // LARGER than before for a caller (subtraction only decreases) and must never
        // be inconsistent with a single subtraction.  The bug allows the reentrant
        // inner Collect to not have locked_, so the balance can be reduced twice
        // for one logical Collect call.
        assertTrue(balAfter <= balBefore);
    }
}

contract ReentrantAttacker {
    MY_BANK private c;
    bool private entered;

    constructor(MY_BANK _c) {
        c = _c;
    }

    function doPut(uint256 t) external payable {
        c.Put{value: msg.value}(t);
    }

    function attack() external {
        (, uint256 bal) = c.Acc(address(this));
        c.Collect(bal);
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            // The inner re-entrant Collect: under the reference this reverts due to
            // the nonReentrant lock still being held by the outer call; under the
            // mutant (missing locked_=true) it proceeds and subtracts the balance
            // again, so balAfter < balBefore by more than one subtraction.
            (, uint256 bal) = c.Acc(address(this));
            c.Collect(bal);
        }
    }
}
